use std::{path::Path,sync::Arc};
use dq_analyze::captured_raw_tree_pages::{Policy,Data};
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<dq_analyze::captured_generator_budget::Budget>}
impl dq_analyze::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,dq_analyze::captured_raw_file::RawPolicyViews<'_>)->Result<bool,dq_analyze::captured_reactive_reads::Failure>)->Result<bool,dq_analyze::captured_reactive_reads::Failure>{for(relative,text)in &self.rows{if !dq_analyze::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
struct Text<'a>(&'a Data);impl dq_analyze::baseline::SiteText for Text<'_>{fn site_text(&self,rel:&str,line:usize)->String{self.0.sites().iter().zip(self.0.source_text()).find(|(site,_)|site.rel==rel&&site.line as usize==line).map(|(_,text)|text.clone()).expect("actual delivered raw-tree source line absent")}}
fn record(outcome:&dq_analyze::policy_finish::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
fn register_old(name:&str,reg:&mut lint::Registry){match name{"cooldown"=>old_cooldown::register(reg),"declaration_block"=>old_declaration_block::register(reg),"duplicate_input_key"=>old_duplicate_input_key::register(reg),"interactions"=>old_interactions::register(reg),"latent"=>old_latent::register(reg),"pollers"=>old_pollers::register(reg),"read_back"=>old_read_back::register(reg),"cap_bits"=>old_cap_bits::register(reg),"pool"=>old_pool::register(reg),_=>panic!("unknown fixture policy")}}
fn register_shared(name:&str,reg:&mut lint::Registry){match name{"cooldown"=>dq_analyze::lints::cooldown::register(reg),"declaration_block"=>dq_analyze::lints::declaration_block::register(reg),"duplicate_input_key"=>dq_analyze::lints::duplicate_input_key::register(reg),"interactions"=>dq_analyze::lints::interactions::register(reg),"latent"=>dq_analyze::lints::latent::register(reg),"pollers"=>dq_analyze::lints::pollers::register(reg),"read_back"=>dq_analyze::lints::read_back::register(reg),"cap_bits"=>dq_analyze::lints::cap_bits::register(reg),"pool"=>dq_analyze::lints::pool::register(reg),_=>panic!("unknown fixture policy")}}
fn failure(error:dq_analyze::captured_reactive_reads::Failure)->Box<dyn std::error::Error>{match error{dq_analyze::captured_reactive_reads::Failure::Operational(actual)=>Box::new(actual),dq_analyze::captured_reactive_reads::Failure::Unsupported(message)=>message.into()}}
fn main()->Result<(),Box<dyn std::error::Error>>{use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/raw_eight_raw_name_match.rs"))),"93e84e840c3066875a3a86f4bd56186f3cb5c16e");assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/raw_eight_cooldown.rs"))),"9ae2e78e471efeed5f9f1e6e64a278278926fc26");
assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/raw_eight_declaration_block.rs"))),"a7b0d2d98cc203c5c23fed1bc0b679657bfebfc0");
assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/raw_eight_duplicate_input_key.rs"))),"ee1fa54f29bfce8808cc1decf983a78925769f92");
assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/raw_eight_interactions.rs"))),"eb853d3578b238620b74157513b8438d5086bc1d");
assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/raw_eight_latent.rs"))),"ebece380fa0cbf1e593fc6b45189b9f52f6b45c2");
assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/raw_eight_pollers.rs"))),"b7dd9847d35e21a82f83cfdf2d10b0cdb8924556");
assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/raw_eight_read_back.rs"))),"b75f323dd9fbff448b1a93e61c3d1bb8ad17d9a8");
assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/raw_eight_cap_bits.rs"))),"685d202150e74f901dd6abbc7f553b338960dbf2");
assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/pool_workspace.rs"))),"e772f1c573731acecfef8c9e647b8e295ddd3c09");
assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/pool_workspace_policy.rs"))),"58e3e3bf0574585c4d94baf506b336069c5d831c");
 for configured in [false,true]{for(name,policy)in[("cooldown",Policy::Cooldown),("declaration_block",Policy::DeclarationBlock),("duplicate_input_key",Policy::DuplicateInputKey),("interactions",Policy::Interactions),("latent",Policy::Latent),("pollers",Policy::Pollers),("read_back",Policy::ReadBack),("cap_bits",Policy::CapBits),("pool",Policy::Pool)]{let root=test_scratch::dir(&format!("whole-raw-tree-{name}-{configured}"));let configuration=fixture::configuration(configured);for(relative,text)in fixture::FILES{let target=root.join(relative);std::fs::create_dir_all(target.parent().ok_or("fixture parent")?)?;std::fs::write(target,text.as_bytes())?;}let config_path=root.join("tools/ci/lint_scopes.toml");std::fs::create_dir_all(config_path.parent().ok_or("config parent")?)?;std::fs::write(&config_path,&configuration)?;
 let options=dq_analyze::run::Options{root:root.clone(),lints:vec![name.into()],raw:true,no_cache:true,..Default::default()};let mut registry=lint::Registry::default();register_old(name,&mut registry);let old=dq_analyze::run::Engine::new(registry,options.clone())?;let expected=old.run_one(old.reg.lints[0].as_ref());assert!(expected.internal_error.is_none(),"{name}: {:?}",expected.internal_error);if !configured{assert!(!expected.run.sites.is_empty(),"genuine source must trigger {name}");}if name=="pool"{assert!(expected.allow_used.is_empty());assert_eq!(expected.run.notes,vec![format!("pool_lint: {} problem(s)",expected.run.sites.len())]);assert!(expected.run.sites.iter().all(|site|site.rel=="code/pool_use.dm"));assert!(expected.run.sites.iter().any(|site|site.rule=="take_leak"));assert_eq!(expected.run.sites.iter().any(|site|site.rule=="new_pooled"),!configured,"generic exemption removes pooled declaration facts, named prefix only suppresses judgments");}if name=="read_back"{let lines=expected.run.sites.iter().map(|site|old.tree.site_text(&site.rel,site.line as usize)).collect::<Vec<_>>();assert!(lines.iter().any(|line|line.contains("event.answer = 1")),"original direct handler positive");assert!(lines.iter().any(|line|line.contains("answers += 2")),"original list alias positive");assert!(!expected.run.sites.iter().any(|site|site.rel=="code/selected_handler.dm"),"exempt schema still answers selected cross-file handler");assert!(!lines.iter().any(|line|line.contains("event.answer = 4")||line.contains("src.answer = 5")),"sender and fill remain excluded");assert!(expected.allow_used.iter().any(|value|value.name=="read_back"),"actual direct-line ALLOW branch");}let mut registry=lint::Registry::default();register_shared(name,&mut registry);let shared=dq_analyze::run::Engine::new(registry,options)?;let delegated=shared.run_one(shared.reg.lints[0].as_ref());assert_eq!(record(&delegated),record(&expected),"entire frozen original/shared {name}");
 let budget=dq_analyze::captured_generator_budget::Budget::new(64*1024*1024)?;let mut rows=Vec::new();for(relative,text)in fixture::FILES{if !policy.selects_path(relative){continue}let source=dm_preprocess::AcquiredSource::from_original_bytes(text.as_bytes().to_vec(),());rows.push(((*relative).to_string(),source.lease().source_text().clone()));}rows.reverse();let pages=Pages{root:&root,rows,budget:Arc::clone(&budget)};let config=dq_analyze::captured_raw_file::Config::capture(dq_analyze::captured_raw_policy::Configuration::Captured(configuration.as_bytes()))?;let data=dq_analyze::captured_raw_tree_pages::collect(&pages,policy,&config,&budget,&||Ok(())).map_err(failure)?;assert_eq!(data.sites(),expected.run.sites.as_slice(),"complete sites {name}");assert_eq!(data.allow_used(),expected.allow_used.as_slice(),"ordered ALLOW {name}");assert_eq!(data.notes(),expected.run.notes.as_slice(),"ordered notes {name}");for(site,text)in data.sites().iter().zip(data.source_text()){assert_eq!(*text,old.tree.site_text(&site.rel,site.line as usize),"as-of line {name}");}
 let empty=Default::default();let scope=config.borrowed_report_scope(name,"").unwrap_or(&empty);let actual=dq_analyze::policy_finish::finish_report(policy.metadata(),scope,&Text(&data),lint::Run{sites:data.sites().to_vec(),notes:data.notes().to_vec()},data.allow_used().to_vec(),Default::default(),&root,&None,true,|_,_,_|panic!("raw eight have no custom finish"),|_,_|false);assert_eq!(record(&actual),record(&expected),"entire immutable old/native report {name}");if !configured{println!("OLD_RAW_TREE_FULL={}",serde_json::json!({"name":name,"record":{"sites":expected.run.sites,"source_text":expected.run.sites.iter().map(|site|old.tree.site_text(&site.rel,site.line as usize)).collect::<Vec<_>>(),"notes":expected.run.notes,"allow_used":expected.allow_used}}));}println!("RAW_TREE_WHOLE_ORIGINAL_NATIVE={}",serde_json::json!({"name":name,"configured":configured,"record":record(&actual)}));
 }}Ok(())}
